def evolution_worker_chat_messages(messages: list[dict]) -> list[dict]:
    """Render protected rollout observations as complete native tool exchanges."""
    out = []
    index = 0
    while index < len(messages):
        row = messages[index]
        index += 1
        if not isinstance(row, dict):
            continue
        role = row.get("role")
        if role == "assistant" and isinstance(row.get("tool_calls"), list):
            out.append(dict(row))
            while index < len(messages) and messages[index].get("role") == "tool":
                out.append(dict(messages[index]))
                index += 1
        elif role == "assistant":
            action = parse_json_object(str(row.get("content", "")), {})
            calls = action.get("tool_calls") or []
            next_row = messages[index] if index < len(messages) else {}
            if isinstance(calls, list) and calls and next_row.get("role") == "tool":
                try:
                    results = json.loads(str(next_row.get("content", "[]")))
                except (ValueError, TypeError):
                    results = []
                results = list(results) if isinstance(results, list) else []
                native = []
                observations = []
                for call_index, call in enumerate(calls[:8]):
                    if not isinstance(call, dict) or not call.get("name"):
                        continue
                    call_id = f"evolution-call-{index}-{call_index}"
                    name = str(call["name"])
                    arguments = dict(call.get("arguments", {})) if isinstance(call.get("arguments"), dict) else {}
                    match = next((i for i, result in enumerate(results) if isinstance(result, dict) and result.get("name") == name), None)
                    observation = results.pop(match) if match is not None else {"name": name, "ok": False, "output": "Kernel did not retain this observation"}
                    native.append({"id": call_id, "type": "function", "function": {
                        "name": name, "arguments": json_dumps(arguments)}})
                    observations.append({"role": "tool", "tool_call_id": call_id, "name": name,
                                         "content": json_dumps(observation)})
                out.append({"role": "assistant", "content": str(action.get("final", "") or ""), "tool_calls": native})
                out.extend(observations)
                index += 1
            else:
                out.append({"role": "assistant", "content": str(action.get("final", "") or row.get("content", "")),
                            **({"reasoning_content": row["reasoning_content"]} if row.get("reasoning_content") else {})})
        elif role in {"user", "system"}:
            out.append({"role": role, "content": str(row.get("content", "") or "")})
        elif role == "tool":
            out.append({"role": "user", "content": "Retained tool observations: " + str(row.get("content", ""))})
    return compact_successful_write_history(out)

